'use client';
import { copy as uiText } from '../../lib/i18n/ui';
/* eslint-disable @next/next/no-img-element -- These bounded assets are generated by the world builder. */
import type { SceneDoc } from '@just-imagine/scene-schema';
import { useLanguage } from '../../lib/i18n';
import { UiIcon } from '../UiIcon';

export function WorldCast({
  doc,
  activeId,
  onMeet,
  onReturn,
}: {
  doc: SceneDoc;
  activeId?: string;
  onMeet: (id: string) => void;
  onReturn: () => void;
}) {
  const { t } = useLanguage();
  const cast = doc.entities.filter((entity) => entity.character);
  if (!cast.length) return null;
  const selected = cast.find((entity) => entity.id === activeId);
  return (
    <section className="world-cast" aria-label={t('worldCast.title')}>
      <div className="world-cast-heading">
        <h2>{t('worldCast.title')}</h2>
        <p role="status">
          {selected
            ? t('worldCast.talking', { name: selected.character!.name })
            : t('worldCast.invitation')}
        </p>
      </div>
      <div className="world-cast-characters">
        {cast.map((entity) => (
          <button
            key={entity.id}
            type="button"
            className="world-character"
            aria-pressed={entity.id === activeId}
            aria-label={t('worldCast.meet', { name: entity.character!.name })}
            onClick={() => onMeet(entity.id)}
          >
            {entity.asset?.status === 'ready' &&
              (entity.asset.animation ? (
                <svg
                  width={52}
                  height={52}
                  viewBox={`0 0 ${entity.asset.width / entity.asset.animation.columns} ${entity.asset.height / entity.asset.animation.rows}`}
                  overflow="hidden"
                  aria-hidden="true"
                >
                  <image
                    href={entity.asset.url}
                    width={entity.asset.width}
                    height={entity.asset.height}
                  />
                </svg>
              ) : (
                <img src={entity.asset.url} alt="" width={52} height={52} />
              ))}
            <span>{uiText(entity.character!.name)}</span>
          </button>
        ))}
        {selected && (
          <button type="button" className="world-character is-return" onClick={onReturn}>
            <UiIcon name="back" />
            <span>{t('worldCast.return')}</span>
          </button>
        )}
      </div>
    </section>
  );
}
